contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    fallback() external payable {}
    receive() external payable {}
    function run(address from, address[] memory _tos, uint v) public payable {
        require(address(this).balance >= 0);
        bool reverted;
        bool ok;
        if (_tos.length == 0) {
            try c.transfer(from, address(this), _tos, v) returns (bool r) {
                reverted = false; ok = r;
            } catch {
                reverted = true; ok = false;
            }
        } else {
            try c.transfer(from, address(this), _tos, v) returns (bool r) {
                reverted = false; ok = r;
            } catch {
                reverted = true; ok = false;
            }
        }
        assert((reverted && _tos.length == 0) || (!reverted && ok));
    }
}

